<script type="module">
    // ===========================================
    // 静态角色元数据
    // ===========================================
    var charMeta = [
        { id: 0, key: "桃汐", name: "桃汐", subtitle: "20岁 · 南方联合大学 · 教育学", breed: "布偶猫", breedColor: "#ffeef2", initial: "桃汐", quote: "喵喵喵？", statusColor: "#e88ca5" },
        { id: 1, key: "苏小兰", name: "苏小兰", subtitle: "21岁 · 云溪大学 · 汉语言文学", breed: "英国短毛猫", breedColor: "#dce8f5", initial: "小兰", quote: "喵...", statusColor: "#7eb8da" },
        { id: 2, key: "阮萌萌", name: "阮萌萌", subtitle: "14岁 · 城西初中 · 初二", breed: "西伯利亚森林猫", breedColor: "#f0ebe0", initial: "萌萌", quote: "喵呜？", statusColor: "#c9a86c" },
        { id: 3, key: "夜琉", name: "夜琉", subtitle: "30岁 · 画廊「疏影」主理人", breed: "俄罗斯蓝猫", breedColor: "#e8e8f0", initial: "夜琉", quote: "嗯？", statusColor: "#8a80a0" },
        { id: 4, key: "青相宜", name: "青相宜", subtitle: "20岁 · 南方联合大学 · 应用心理学", breed: "布偶猫", breedColor: "#e8f5ec", initial: "相宜", quote: "喵...不可以咬哦？", statusColor: "#8a7eb8" },
        { id: 5, key: "北奈", name: "北奈", subtitle: "19岁 · 南方联合大学 · 汉语言文学", breed: "玄猫", breedColor: "#e8e8f0", initial: "北奈", quote: "懒得理你喵。", statusColor: "#808898" }
    ];

    // 运行时角色数据（MVU 填充）
    var characters = [];

    function getAffectionStatus(v) {
        if (v >= 90) return '依恋'; if (v >= 70) return '心动';
        if (v >= 50) return '亲近'; if (v >= 30) return '友好';
        if (v >= 20) return '初识'; return '陌生';
    }
    function getLibidoStatus(v) {
        if (v >= 80) return '渴求'; if (v >= 60) return '强烈';
        if (v >= 30) return '微妙'; return '平静';
    }
    function pickAvatar(lib, av0, av1, av2) {
        if (lib >= 85 && av2) return av2;
        if (lib >= 70 && av1) return av1;
        return av0;
    }

    // ===========================================
    // 从 MVU 拉取所有动态值
    // ===========================================
    // ===========================================
    // 主题切换
    // ===========================================
    (function() {
        var toggle = document.getElementById('themeToggle');
        if (!toggle) return;
        var saved = null;
        try { saved = localStorage.getItem('nekogo_theme'); } catch(e) {}
        if (saved === 'dark') {
            document.documentElement.setAttribute('data-theme', 'dark');
            toggle.innerHTML = '&#x2600;';
        }
        toggle.addEventListener('click', function() {
            var cur = document.documentElement.getAttribute('data-theme');
            if (cur === 'dark') {
                document.documentElement.removeAttribute('data-theme');
                toggle.innerHTML = '&#x25D0;';
                try { localStorage.setItem('nekogo_theme', 'light'); } catch(e) {}
            } else {
                document.documentElement.setAttribute('data-theme', 'dark');
                toggle.innerHTML = '&#x2600;';
                try { localStorage.setItem('nekogo_theme', 'dark'); } catch(e) {}
            }
        });
    })();

    // ===========================================
    // 折叠切换
    // ===========================================
    var isCollapsed = false;
    (function() {
        var btn = document.getElementById('collapseBtn');
        var app = document.getElementById('app');
        if (!btn || !app) return;

        // Restore saved state
        try {
            if (localStorage.getItem('nekogo_collapsed') === '1') {
                isCollapsed = true;
                app.classList.add('collapsed');
            }
        } catch(e) {}

        btn.addEventListener('click', function() {
            isCollapsed = !isCollapsed;
            if (isCollapsed) {
                app.classList.add('collapsed');
            } else {
                app.classList.remove('collapsed');
            }
            try { localStorage.setItem('nekogo_collapsed', isCollapsed ? '1' : '0'); } catch(e) {}
        });
    })();

    function refreshFromMVU() {

        var vars = getAllVariables();
        var stats = _.get(vars, 'stat_data', {});

        // 世界信息
        worldData.date    = _.get(stats, '世界信息.日期时间', '');
        worldData.weather = _.get(stats, '世界信息.天气', '');
        worldData.wind    = _.get(stats, '世界信息.风力', '');
        worldData.loc     = _.get(stats, '世界信息.地点', '');

        // 4 角色
        characters = charMeta.map(function(meta) {
            var k = meta.key;
            var lib   = _.get(stats, k + '.性欲值', 0);
            var av0   = _.get(stats, k + '.头像通常', '');
            var av1   = _.get(stats, k + '.头像羞恥', '');
            var av2   = _.get(stats, k + '.头像発情', '');
            return {
                id: meta.id,
                name: meta.name,
                subtitle: meta.subtitle,
                breed: meta.breed,
                breedColor: meta.breedColor,
                initial: meta.initial,
                quote: meta.quote,
                statusColor: meta.statusColor,
                affection:    _.get(stats, k + '.好感度', 0),
                relationship: _.get(stats, k + '.关系', ''),
                libido:       lib,
                clothing:     _.get(stats, k + '.服饰', ''),
                innerThought: _.get(stats, k + '.内心想法', ''),
                heatPeriod:   _.get(stats, k + '.发情期', ''),
                avatar:       pickAvatar(lib, av0, av1, av2)
            };
        });

        // Auto-switch to character whose variables changed
        var prev = window._nekogoPrevChars;
        if (prev && prev.length === characters.length) {
            for (var ci = 0; ci < characters.length; ci++) {
                var p = prev[ci];
                var cur = characters[ci];
                if (p.affection !== cur.affection ||
                    p.libido !== cur.libido ||
                    p.clothing !== cur.clothing ||
                    p.innerThought !== cur.innerThought ||
                    p.relationship !== cur.relationship) {
                    if (ci !== currentIndex) {
                        currentIndex = ci;
                        try { localStorage.setItem('nekogo_charIndex', ci); } catch(e) {}
                    }
                    break;
                }
            }
        }
        window._nekogoPrevChars = characters.map(function(c) { return {
            affection: c.affection, libido: c.libido,
            clothing: c.clothing, innerThought: c.innerThought,
            relationship: c.relationship
        };});

        renderCharacterList();
        if (currentIndex >= characters.length) currentIndex = 0;
        updateDisplay(characters[currentIndex] || characters[0]);
        updateWorldBar();
    }

    // ===========================================
    // DOM refs
    // ===========================================
    var currentIndex = (function() {
        try { var v = localStorage.getItem('nekogo_charIndex'); return v !== null ? parseInt(v) : 0; } catch(e) { return 0; }
    })(), isTransitioning = false;
    var charAvatar = document.getElementById('charAvatar');
    var avatarPlaceholder = document.getElementById('avatarPlaceholder');
    var avatarInitial = document.getElementById('avatarInitial');
    var avatarBreed = document.getElementById('avatarBreed');
    var charName = document.getElementById('charName');
    var charSubtitle = document.getElementById('charSubtitle');
    var affectionBar = document.getElementById('affectionBar');
    var affectionText = document.getElementById('affectionText');
    var affectionStatus = document.getElementById('affectionStatus');
    var relationText = document.getElementById('relationText');
    var libidoBar = document.getElementById('libidoBar');
    var libidoText = document.getElementById('libidoText');
    var libidoStatus = document.getElementById('libidoStatus');
    var heatPeriod = document.getElementById('heatPeriod');
    var quoteText = document.getElementById('quoteText');
    var clothingDesc = document.getElementById('clothingDesc');
    var innerThought = document.getElementById('innerThought');
    var characterMain = document.getElementById('characterMain');
    var listContainer = document.getElementById('charListContainer');

    // ===========================================
    // 渲染
    // ===========================================
    function renderCharacterList() {
        listContainer.innerHTML = '';
        for (var i = 0; i < characters.length; i++) {
            (function(index) {
                var ch = characters[index];
                var card = document.createElement('div');
                card.className = 'char-card' + (index === currentIndex ? ' active' : '');
                card.onclick = function() { switchCharacter(index); };

                var avDiv = document.createElement('div');
                avDiv.className = 'card-avatar';
                if (ch.avatar) {
                    avDiv.innerHTML = '<img src="' + ch.avatar + '" alt="' + ch.name + '">';
                } else {
                    avDiv.style.background = 'linear-gradient(160deg, ' + ch.breedColor + ', rgba(255,255,255,0.2))';
                    avDiv.textContent = ch.initial;
                }

                var nm = document.createElement('div'); nm.className = 'cname'; nm.textContent = ch.name;
                var af = document.createElement('div'); af.className = 'caff'; af.textContent = '❤ ' + ch.affection;
                var tg = document.createElement('div'); tg.className = 'status-tag'; tg.textContent = getAffectionStatus(ch.affection);

                card.appendChild(avDiv); card.appendChild(nm); card.appendChild(af); card.appendChild(tg);
                listContainer.appendChild(card);
            })(i);
        }
    }

    function switchCharacter(index) {
        if (index === currentIndex || isTransitioning) return;
        if (index < 0 || index >= characters.length) return;
        isTransitioning = true;
        characterMain.classList.add('fade-out');
        setTimeout(function() {
            currentIndex = index;
            try { localStorage.setItem('nekogo_charIndex', index); } catch(e) {}
            updateDisplay(characters[index]);
            characterMain.classList.remove('fade-out');
            isTransitioning = false;
        }, 300);
    }

    function updateDisplay(ch) {
        if (!ch) return;
        if (ch.avatar) {
            charAvatar.src = ch.avatar; charAvatar.style.display = ''; avatarPlaceholder.style.display = 'none';
        } else {
            charAvatar.style.display = 'none'; avatarPlaceholder.style.display = 'flex';
            avatarPlaceholder.style.background = 'linear-gradient(160deg, ' + ch.breedColor + ', rgba(255,255,255,0.2))';
            avatarInitial.textContent = ch.initial; avatarBreed.textContent = ch.breed;
        }
        charName.textContent = ch.name;
        charSubtitle.textContent = ch.subtitle;
        affectionBar.style.width = ch.affection + '%';
        affectionText.textContent = ch.affection + '/100';
        affectionStatus.textContent = getAffectionStatus(ch.affection);
        relationText.textContent = ch.relationship || '---';
        libidoBar.style.width = ch.libido + '%';
        libidoText.textContent = ch.libido + '/100';
        libidoStatus.textContent = getLibidoStatus(ch.libido);
        quoteText.textContent = ch.quote;
        clothingDesc.textContent = ch.clothing || '---';
        innerThought.textContent = ch.innerThought || '---';
        heatPeriod.textContent = ch.heatPeriod || '---';

        var cards = document.querySelectorAll('.char-card');
        for (var i = 0; i < cards.length; i++) cards[i].classList.toggle('active', i === currentIndex);
        if (cards[currentIndex]) {
            var scrollContainer = document.getElementById('charListContainer');
            var card = cards[currentIndex];
            var containerLeft = scrollContainer.getBoundingClientRect().left;
            var cardLeft = card.getBoundingClientRect().left;
            var offset = cardLeft - containerLeft + scrollContainer.scrollLeft - (scrollContainer.clientWidth - card.offsetWidth) / 2;
            scrollContainer.scrollTo({ left: offset, behavior: 'smooth' });
        }
    }

    function navigateChar(d) {
        var n = currentIndex + d;
        if (n < 0) n = characters.length - 1;
        if (n >= characters.length) n = 0;
        switchCharacter(n);
    }

    // ===========================================
    // 图片放大
    // ===========================================
    function openLightbox() {
        var img = document.getElementById('charAvatar');
        if (!img || !img.src || img.style.display === 'none') return;
        document.getElementById('lightboxImg').src = img.src;
        document.getElementById('lightbox').classList.add('active');
    }
    function closeLightbox() {
        document.getElementById('lightbox').classList.remove('active');
    }

    // ===========================================
    // 键盘 & 触控
    // ===========================================
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape')     { closeLightbox(); }
    });


    // ===========================================
    // 世界时钟
    // ===========================================
    var worldData = { date: '', weather: '', wind: '', loc: '' };
    function updateWorldBar() {
        document.getElementById('worldDate').textContent = worldData.date || '----年--月--日';
        document.getElementById('worldWeather').textContent = worldData.weather || '---';
        document.getElementById('worldWind').textContent = worldData.wind || '---';
        document.getElementById('worldLoc').textContent = worldData.loc || '---';
    }

    // ===========================================
    // MVU 初始化 + 事件监听
    // ===========================================
    async function init() {
        await waitGlobalInitialized('Mvu');
        refreshFromMVU();
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function() {
            refreshFromMVU();
        });
        // Bind lightbox handlers
        document.getElementById('navPrev').addEventListener('click', function() { navigateChar(-1); });
        document.getElementById('navNext').addEventListener('click', function() { navigateChar(1); });
        var af = document.getElementById('avatarFrame');
        if (af) af.addEventListener('click', function(e) { e.stopPropagation(); openLightbox(); });
        var zi = document.querySelector('.zoom-icon');
        if (zi) zi.addEventListener('click', function(e) { e.stopPropagation(); openLightbox(); });
        var lb = document.getElementById('lightbox');
        var lbClose = document.querySelector('.lightbox-close');
        if (lb) lb.addEventListener('click', function(e) { if (e.target === lb) closeLightbox(); });
        if (lbClose) lbClose.addEventListener('click', function(e) { e.stopPropagation(); closeLightbox(); });
        document.addEventListener('keydown', function(e) { if (e.key === 'Escape') closeLightbox(); });
    }
    $(errorCatched(init));
</script>



